    "speaker_id": null
  },
  {
    "kind": "action",
    "text": "Ash waits patiently.",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null
  },
  {
    "kind": "dialogue",
    "text": "\"Grain and oilskins.\" Ash responds to Wren.",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "9a6851da-43ee-480a-a459-0c3e77a2465f"
  }
]

[
  {
    "kind": "narration",
    "text": "Ash waits patiently, his gaze fixed on the distant lighthouse.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "action",
    "text": "Meanwhile, Wren tries to engage Ash in conversation.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "595816fb-b269-43b6-8da0-6a8c26dd55fd",
    "text": "\"Old Marlow, if the lamp is still lit.\" Ash responds to Wren's query.",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking if the stalls are open yet.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash, patiently waiting, responds to Wren's query.",
    "cited_fact_keys": ["attempt:wait", "reaction:1"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "c804a210-3087-4ffe-80fd-5890e817f011",
    "text": "\"Stalls open at second bell.\"",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Ash stood still, waiting.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "narration",
    "text": "Meanwhile, Wren tried to get Ash's attention, eager to discuss the dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"]
  }
]

[
  {
    "kind": "narration",
    "text": "Marlow and Wren attempt to communicate with Ash, each with their own messages.",
    "cited_fact_keys": ["attempt:communicate", "attempt:communicate"],
    "speaker_id": null
  },
  {
    "kind": "narration",
    "text": "Ash waits patiently for their attempts to reach him.",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null
  },
  {
    "kind": "dialogue",
    "text": "Aye, and mind the loose stones past the bridge.",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "beb03d24-74c7-467d-9cc3-744e2a9f83bf"
  },
  {
    "kind": "dialogue",
    "text": "Dawn bell means the first stalls are opening.",
    "cited_fact_keys": ["reaction:2"],
    "speaker_id": "fe1afce1-2f18-4100-9a4b-28b70af800a8"
  }
]

[
  {
    "kind": "narration",
    "text": "Ash waits patiently, his eyes fixed on the horizon.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "narration",
    "text": "Wren attempts to engage Ash in conversation, the topic at hand being the dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Marlow, ever the observant one, watches the scene unfold.",
    "cited_fact_keys": ["attempt:observe"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "0bba4d24-88b9-4543-8d77-f7117260225f",
    "text": "Dawn bell means the market's waking.",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking about their journey ahead.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "5f0d1e47-a6f4-4cf2-83bd-4b54d5d0be60",
    "text": "Ash says to Wren: 'Dawn bell means the market is waking early today, so hurry down with coin and basket before the best bread and freshest fish are gone from the stalls.'",
    "cited_fact_keys": ["reaction:1"]
  },
  {
    "kind": "narration",
    "text": "Meanwhile, Ash waits patiently for Wren's response.",
    "cited_fact_keys": ["attempt:wait"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking, 'Is the old bridge safe to cross?'",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "action",
    "text": "Ash waits for Wren's response.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "17f37dc2-cf4c-4730-b0b8-d13bdf28dd44",
    "text": "'No,' Ash says to Wren.",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking, 'What news from the mill, Ash?'",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "action",
    "text": "Ash waits for Wren's response.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "4b135b1c-48da-4a54-bdb2-5743b141d486",
    "text": "It's still standing, unless someone's moved it.",
    "cited_fact_keys": ["reaction:1"]
  }
]
